-- Generated by scripts/build-ai-task-sources-catalog.ts.
-- INERT ON APPLY: the policy is active=false, so Bob is not offered the tool.
-- Deploy ask-bob AND bob-worker with its handler before enabling the policy
-- in a separate owner-approved change (FORM package 5).
begin;
do $task_sources_catalog$
declare contracts jsonb:=$task_sources_contracts$[
  {
    "name": "read_task_sources",
    "description": "Collect the governing sources for the next piece of work in one read: the selected Solution revision with its features and open choices, the Step completion requirements and the exact Construction revision state, with coverage, conflicts and reopen pointers.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "area_id",
        "step_id",
        "construction"
      ],
      "properties": {
        "area_id": {
          "type": [
            "string",
            "null"
          ],
          "maxLength": 200,
          "description": "Area of the work, or null for the whole project."
        },
        "step_id": {
          "type": [
            "string",
            "null"
          ],
          "maxLength": 200,
          "description": "Plan Step whose completion requirements apply, or null."
        },
        "construction": {
          "anyOf": [
            {
              "type": "null"
            },
            {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "artifact_id",
                "revision"
              ],
              "properties": {
                "artifact_id": {
                  "type": "string",
                  "format": "uuid"
                },
                "revision": {
                  "type": "integer",
                  "minimum": 1,
                  "maximum": 999999999
                }
              }
            }
          ],
          "description": "Exact saved Construction revision the work continues from, or null."
        }
      }
    }
  }
]$task_sources_contracts$::jsonb;
 policies jsonb:=$task_sources_policies$[
  {
    "name": "read_task_sources",
    "description": "Collect the governing sources for the next piece of work in one read.",
    "how_to": "Pass the Area (null for the whole project), the plan Step whose completion requirements apply (or null) and the exact saved Construction revision when one exists. Returns the selected Solution's features and open choices, the Step requirements and the Construction's freshness, Solution pin and FORM scope, with exact revisions, open items, conflicts and coverage. Reopen originals through the returned pointers. Private conversation, images and the meaning of free text are not included; nothing here approves a design, measurement or fabrication.",
    "schema_version": 1,
    "always_load": false,
    "preload_phases": [],
    "active": false
  }
]$task_sources_policies$::jsonb;
 patch jsonb; policy jsonb; prior shared.ai_prompt_versions; template shared.ai_prompt_versions;
 prompt_uuid uuid; version_uuid uuid; next_version integer; definition jsonb; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 select v.* into template from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.read_construction_changes';
 if not found then raise exception 'bound_edit_template_missing'; end if;
 for patch in select value from jsonb_array_elements(contracts) loop
  select value into policy from jsonb_array_elements(policies) where value->>'name'=patch->>'name';
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.'||(patch->>'name');
  if not found then
   insert into shared.ai_prompts(app,prompt_key,label,description,content,flow,definition_kind)
    values('bob','tools.'||(patch->>'name'),policy->>'description',policy->>'description','','','tool_contract') returning id into prompt_uuid;
   prior:=template;
  else
   if prior.metadata->>'publication'='task-sources-v1' then return;end if;
   prompt_uuid:=prior.prompt_id;
  end if;
  definition:=prior.definition||patch||jsonb_build_object('handler',patch->>'name','required_parameters',patch#>'{parameters,required}','optional_parameters','[]'::jsonb,'additional_description',policy->>'how_to','card_description',policy->>'description');
  definition:=jsonb_set(definition,'{envelope,schema_version}','1'::jsonb);
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prompt_uuid;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prompt_uuid,next_version,'tool_contract',1,jsonb_build_object('publication','task-sources-v1','server_fields','[]'::jsonb),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object('tools.'||(patch->>'name'),version_uuid);
 end loop;
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='bob.tools' for update of p;
 if not found then raise exception 'bound_edit_toolbox_missing'; end if;
 definition:=prior.definition;
 for policy in select value from jsonb_array_elements(policies) loop
  insert into bob.tool_catalog(name,description,how_to,schema_version,always_load,preload_phases,active)
   values(policy->>'name',policy->>'description',policy->>'how_to',(policy->>'schema_version')::integer,(policy->>'always_load')::boolean,array(select jsonb_array_elements_text(policy->'preload_phases')),(policy->>'active')::boolean)
   on conflict(name) do nothing;
  if not exists(select 1 from jsonb_array_elements(definition->'catalog') r where r->>'name'=policy->>'name') then
   definition:=jsonb_set(definition,'{catalog}',definition->'catalog'||jsonb_build_array(policy));
  end if;
  if not definition->'contract_keys'?('tools.'||(policy->>'name')) then
   definition:=jsonb_set(definition,'{contract_keys}',definition->'contract_keys'||jsonb_build_array('tools.'||(policy->>'name')));
  end if;
  definition:=jsonb_set(definition,'{shelves}',(select jsonb_agg(case when shelf->>'label'='Project records and memory' and not shelf->'tools'?(policy->>'name') then jsonb_set(shelf,'{tools}',shelf->'tools'||jsonb_build_array(policy->>'name')) else shelf end) from jsonb_array_elements(definition->'shelves') shelf));
 end loop;
 select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','task-sources-v1'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=activation||jsonb_build_object('bob.tools',version_uuid);
 perform shared.activate_ai_catalog('bob',activation);
end $task_sources_catalog$;
commit;
